<?php
namespace App\Services\Shipping;
use App\Services\Shipping\Data\{UnifiedQuoteRequest,UnifiedQuoteResponse};use App\Services\Shipping\Providers\{XpertaEstafetaQuoteProvider,ContractualEstafetaQuoteProvider};use RuntimeException;
final class UnifiedShippingQuoteService {public function __construct(private ProviderStrategyResolver $resolver,private XpertaEstafetaQuoteProvider $xperta,private ContractualEstafetaQuoteProvider $contractual){}public function quote(UnifiedQuoteRequest $request,string $environment='stage',bool $experimental=false):UnifiedQuoteResponse{if(!$experimental&&!config('services.shipping.unified_quote_enabled',false))throw new RuntimeException('ZIGO_B2C_UNIFIED_QUOTE_ENABLED está deshabilitado.');$decision=$this->resolver->resolve('quote',$request->carrier,$environment);$provider=match($decision['strategy']){'xperta_estafeta'=>$this->xperta,'contractual_local'=>$this->contractual,default=>null};if(!$provider)throw new RuntimeException('Cotización no disponible: '.implode(',',$decision['reasons']??[]));return$provider->quote($request);}}
